from pathlib import Path
import sys,json
BASE=Path(__file__).resolve().parents[1]
LANG=sys.argv[1] if len(sys.argv)>1 else "zh"
if LANG not in ("zh","en"):raise SystemExit("Language must be zh or en")
D=json.loads((BASE/f"data/catalogue.{LANG}.json").read_text(encoding="utf-8"))
DOMAINS=json.loads((BASE/f"data/domains.{LANG}.json").read_text(encoding="utf-8"))
import json,html,collections,base64
E=html.escape
names={k:n for k,n,_ in DOMAINS}
groups={'paid':'商业付费','open':'免费与开源','limited':'免费 / 授权受限'}
counts=collections.Counter(d['group'] for d in D)
routes={'api':'API / 代码','script':'脚本 / 命令行','gui':'GUI / 接口待确认'}
sources_count=len({s['url'] for d in D for s in d['sources']})
def a(label,url):return f'<a href="{E(url,quote=True)}" target="_blank" rel="noopener noreferrer">{E(label)} ↗</a>'
def state(v):
 k=v['kind'];label={'official':'官方已定位','community':'社区已定位','unverified':'未核实'}[k]
 return f'<span class="status {k}">{label}</span> '+(a(v['text'],v['url']) if 'url' in v else E(v['text']))
def cards():
 out=[]
 for d in D:
  ai=' · '.join(t for t,v in [('MCP',d['mcp']),('Skill',d['skill'])] if v['kind']!='unverified')
  fs=''.join(f'<div class="detail-field"><dt>{k}</dt><dd>{v}</dd></div>' for k,v in [
   ('方法与范围',E(d['method'])),('可编程入口',E(d['api'])),('运行与计算',E(d['compute'])),('授权边界',E(d['license'])),('应用依据',E(d['usage'])),('适用边界',E(d['limit'])),('MCP',state(d['mcp'])),('Agent Skill',state(d['skill']))])
  out.append(f'''<article class="software {d['group']}" data-id="{d['id']}" id="tool-{d['id']}">
<div class="card-meta"><span class="license-dot {d['group']}"></span><span>{groups[d['group']]}</span><label class="compare-label"><input type="checkbox" value="{d['id']}" class="compare-check" aria-label="比较 {E(d['name'],quote=True)}">比较</label></div>
<h3>{E(d['name'])}</h3><p class="card-summary">{E(d['summary'])}</p>
<div class="card-tags"><span class="tag route-{d['route']}">{routes[d['route']]}</span>{f'<span class="tag ai-tag">{ai} 已定位</span>' if ai else ''}</div>
<div class="card-domain">{' / '.join(E(names[c]) for c in d['cats'][:2])}</div>
<details><summary>接口、许可与来源 <span>＋</span></summary><dl>{fs}</dl><div class="sources"><span>原始资料</span>{''.join(a(s['label'],s['url']) for s in d['sources'])}</div></details>
</article>''')
 return '\n'.join(out)
domain_tiles=''.join(f'<button class="domain-tile" data-domain="{k}"><span class="domain-no">{i+1:02}</span><strong>{n}</strong><span>{desc}</span><b>{sum(k in d["cats"] for d in D)} <small>项</small></b></button>' for i,(k,n,desc) in enumerate(DOMAINS))
domain_filters=''.join(f'<button data-domain="{k}">{n}</button>' for k,n,_ in DOMAINS)
agent_rows=''
for d in D:
 if d['mcp']['kind']!='unverified' or d['skill']['kind']!='unverified':
  agent_rows+=f'<tr><th><a href="#tool-{d["id"]}" class="jump-tool" data-jump="{d["id"]}">{E(d["name"])}</a></th><td>{state(d["mcp"])}</td><td>{state(d["skill"])}</td><td>{E(d["api"])}</td></tr>'
methods=[
('光线与辐射输运','位置、方向、功率 / 辐亮度','镜头、照明、杂散光、宏观场景','OpticStudio · CODE V · LightTools · Raysect · Mitsuba','是否需要相位、衍射或偏振？仅有光线轨迹通常不足以回答相干问题。'),
('波前与衍射','复振幅 E(x,y)、偏振与相位','自由空间传播、PSF、全息、AO','POPPY · HCIPy · LightPipes · Diffractio · TorchOptics','标量、近轴和采样条件是否成立？高 NA 或亚波长结构需要更精细模型。'),
('全波电磁','空间电磁场 E、H 与材料响应','亚波长器件、模式、散射、共振','Meep · Lumerical · JCMsuite · COMSOL · Tidy3D','网格 / 基组、色散、PML 和边界是否收敛？不宜把宏观实验台直接整体离散。'),
('结构化求解','层、周期、模态或散射基底系数','薄膜、光栅、晶体、颗粒、波导','tmm · S4 · torcwa · MPB · ADDA · treams','快速来自结构假设；平面层、无限周期、模态截断各自有物理边界。'),
('电路与包络','端口复幅度、S 参数、时间包络','PIC、通信链路、超快光纤、腔系统','SAX · INTERCONNECT · VPI · OptiCommPy · Luna','器件紧凑模型、频率、相位、功率与采样的约定必须统一。'),
('量子态动力学','态矢量、密度矩阵、量子信道','量子光学、耗散、单光子与连续变量','QuTiP · QuantumOptics.jl · Perceval · Strawberry Fields','经典电磁场与量子算符是不同表示；耦合参数需要明确的物理来源。'),
('统计光子输运','光子包权重、路径与时间统计','组织、强散射介质、扩散光学','MCX · MMC','通常不保留相干相位；适合能量与时间分布，不直接模拟干涉。')]
method_rows=''.join('<tr>'+''.join(f'<td>{E(c)}</td>' for c in row)+'</tr>' for row in methods)
workflows=[
('01','镜头 → 图像 → 反演','成像系统的数字模型', [('镜头与公差','OpticStudio / CODE V / Optiland'),('波前与 PSF','prysm / POPPY / HCIPy'),('图像与参数估计','scikit-image / SciPy / PyTorch')], '传递瞳面复场或像差、PSF、像元尺寸、光谱响应和噪声参数；空间坐标与单位保持一致。','从单波长理想点源扩展到实际光谱、像差和探测器响应；用测量数据校准参数。'),
('02','单胞 → 超表面 → 系统','亚波长设计跨越到宏观性能', [('单胞响应库','torcwa / grcwa / S4'),('器件场验证','Meep / Lumerical / Tidy3D'),('传播与成像','Diffractio / TorchOptics / POPPY')], '传递复数透射 / 反射矩阵及角度、偏振、波长依赖，不能只传“相位图”。','局域周期近似会忽略单元耦合与边缘效应；大角度和强梯度区域需要更高保真模型。'),
('03','版图 → 器件 → 电路','可制造 PIC 的数字设计', [('版图与 PDK','gdsfactory / IPKISS / KLayout'),('器件模型','Meep / JCMsuite / Lumerical'),('电路与统计','SAX / INTERCONNECT / VPI')], '传递工艺层、材料、截面、端口及复数 S 参数；记录参考平面、频率和模态归一化。','PDK 决定可制造边界；DRC 合格不等于光学性能合格，理想电路也不等于有工艺容差的电路。'),
('04','脉冲 → 传输 → 接收','超快光学与光通信', [('非线性脉冲','Luna.jl / py-fmas / laserfun'),('器件与链路','RP Fiber Power / VPI / OptiCommPy'),('估计与优化','SciPy / JAX / PyTorch')], '传递复包络、时间网格、中心频率、色散、非线性与噪声定义；区分场幅值和光功率。','宽带脉冲或强非线性可能超出简单包络假设；参数更新应来自实际光纤与器件表征。'),
('05','光机热 → 腔模 → 读出','精密激光与干涉系统', [('热 / 结构模型','COMSOL / 自定义 FEM'),('腔与干涉仪','Finesse / RP Resonator'),('波前与控制分析','HCIPy / SciPy / MATLAB')], '传递热致面形、折射率变化、腔长、模式失配和噪声谱；定义相同的工作点。','多物理场耦合不必让一个求解器承担全部任务；先明确每个子模型向下游传递的物理量。'),
('06','组织 / 样品 → 光传播 → 重建','生物光学与计算成像', [('样品与光学参数','组织网格 / 材料数据库'),('传播模型','MCX / MMC；相干问题选波动模型'),('重建与定量','PyNX / pyDHM / HoloPy / 图像库')], '根据实验模式选择数据：光子通量、时间响应、强度图、衍射图或复场，不能混用。','扩散断层、全息显微与 ptychography 的观测算子不同；重建算法必须匹配实际前向模型。')]
flow_html=''
